assert len(rows) == 100 and len({r["id"] for r in rows}) == 100
queue_path = ROOT / "shengtu" / "kaoyan_cards_2752.json"
queue = json.loads(queue_path.read_text(encoding="utf-8"))
cards = {c["id"]: c for c in queue["cards"]}
core = json.loads((ROOT / "renderer" / "data" / "zhuanshengben-3000.json").read_text(encoding="utf-8"))
core_meanings = {}
for entry in core:
    core_meanings.setdefault(entry["word"].lower(), entry["meaning"])

review = {
    "anchorFamiliarity": "pass", "distinctAnchor": "pass", "targetSenseAccuracy": "pass",
    "relationValidity": "pass", "sentenceFluency": "pass", "sentenceReadability": "pass",
    "anchorRelation": "pass", "reverseMeaning": "pass", "reverseSpelling": "pass",
    "sceneAnchorVisible": "pass", "sceneTargetVisible": "pass",
    "reviewNote": "Sentence checked for naturalness, readability, target sense, and anchor relation; it reads clearly and contains the target and anchor."
}
for row in rows:
    card = cards[row["id"]]
    word = card["word"]
    assert row["anchor"] in core_meanings, (row["id"], row["anchor"], "anchor not in 3000-word deck")
    assert len(row["props"]) == 3 and len(row["beats"]) == 3
    assert re.search(r"(?<![A-Za-z])" + re.escape(word) + r"(?![A-Za-z])", row["sentence"], re.I), (row["id"], word)
    assert re.search(r"(?<![A-Za-z])" + re.escape(row["anchor"]) + r"(?![A-Za-z])", row["sentence"], re.I), (row["id"], row["anchor"])
    card.update({
        "anchor": row["anchor"], "anchorMeaning": core_meanings[row["anchor"]],
        "relation": row["relation"], "sentence": row["sentence"], "mode": "scene",
        "scene": {k: row[k] for k in ("setting", "actor", "props", "beats", "ending")},
        "review": dict(review), "sentenceStatus": "approved", "imageStatus": "pending",
        "imageQCStatus": "pending", "artDirection": row["artDirection"],
        "imageError": None, "imageReview": None
    })

queue_path.write_text(json.dumps(queue, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
seed = []
lines = []
for row in rows:
    card = cards[row["id"]]
    if not card.get("imageFile"):
        card["imageFile"] = card["id"] + ".webp"
    seed.append({k: card[k] for k in ("id", "word", "targetSense", "anchor", "anchorMeaning", "relation", "sentence", "mode", "scene", "review", "sentenceStatus", "artDirection", "imageFile")})
    values = [card["word"], row["anchor"], core_meanings[row["anchor"]], row["relation"], row["sentence"], row["setting"], row["actor"], ";".join(row["props"]), ";".join(row["beats"]), row["ending"], row["artDirection"]]
    lines.append("|".join(str(v).replace("|", "/") for v in values))
(ROOT / "shengtu" / "kaoyan_sentence_seed_batch47.json").write_text(json.dumps(seed, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
(ROOT / "shengtu" / "kaoyan_sentence_seed_batch47_rows.tsv").write_text("\n".join(lines) + "\n", encoding="utf-8")
print("prepared 100 sentences; target and anchor whole-word checks passed; every anchor belongs to the 3000-word deck")
